verify_commands.command:
rtk env PATH="$PWD/.venv/bin:$PATH" .venv/bin/python -c 'import ast, difflib, io, json, os, re, subprocess, tokenize
BASE="88c90f8b5abf4a80be3b1289d7719d6e03e29684"
AFTER=os.environ.get("REBAR_AFTER_REF","HEAD")
SPEC=json.loads("""{"tests/unit/test_engine_root_convention.py":{"docs":["<module>","test_no_test_module_resolves_the_installed_engine_root","split_engine"],"spans":[[1,32],[52,55],[80,85],[138,143]]}}""")
OWNERS=(ast.Module,ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)
PAT=re.compile(r"#\\s*(?:noqa\\b|type:\\s*ignore\\b|pragma:\\s*no cover\\b|pyright:|mypy:|ruff:|pylint:|(?:fmt|isort):\\s*(?:on|off|skip)\\b|nosec\\b|coding[:=]|[A-Za-z][\\w-]*-ok:)",re.I)
def src(ref,path):
 return subprocess.check_output(["git","show",f"{ref}:{path}"],text=True)
def strip_docs(tree,allowed,required):
 seen=set()
 def visit(node,prefix):
  if isinstance(node,ast.Module):
   name="<module>"; child_prefix=prefix
  elif isinstance(node,(ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)):
   name=".".join((*prefix,node.name)); child_prefix=(*prefix,node.name)
  else:
   for child in ast.iter_child_nodes(node): visit(child,prefix)
   return
  if name in allowed and node.body and isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):
   node.body.pop(0); seen.add(name)
  for child in ast.iter_child_nodes(node): visit(child,child_prefix)
 visit(tree,())
 if required: assert seen==set(allowed),f"missing allowlisted docstrings: {sorted(set(allowed)-seen)}"
 return tree
def norm(text,path,allowed,required):
 tree=strip_docs(ast.parse(text,filename=path,type_comments=True),allowed,required)
 for node in ast.walk(tree):
  if isinstance(node,ast.TypeIgnore): node.lineno=0
 return ast.dump(tree,annotate_fields=True,include_attributes=False)
def directives(text):
 lines=text.splitlines()
 picked=[lines[t.start[0]-1] for t in tokenize.generate_tokens(io.StringIO(text).readline) if t.type==tokenize.COMMENT and PAT.search(t.string)]
 return (lines[0] if lines and lines[0].startswith("#!") else ""),picked
def admitted(line,lines,spans):
 return any(s<=line<=e for s,e in spans) or (1<=line<=len(lines) and not lines[line-1].strip() and any(s-1<=line<=e+1 for s,e in spans))
for path,rule in SPEC.items():
 before=src(BASE,path); after=src(AFTER,path)
 assert norm(before,path,rule["docs"],True)==norm(after,path,rule["docs"],False),f"runtime AST changed: {path}"
 assert directives(before)==directives(after),f"directive/shebang changed: {path}"
 a=before.splitlines(); b=after.splitlines()
 for tag,i1,i2,j1,j2 in difflib.SequenceMatcher(a=a,b=b,autojunk=False).get_opcodes():
  if tag=="equal": continue
  if i1==i2:
   assert any(s-1<=i1<=e for s,e in rule["spans"]),f"insertion outside allowlist: {path}:{i1+1}"
  else:
   bad=[line for line in range(i1+1,i2+1) if not admitted(line,a,rule["spans"])]
   assert not bad,f"changed base lines outside allowlist: {path}:{bad}"
print(f"immutable prose oracle PASS: {len(SPEC)} paths at {BASE} -> {AFTER}")'
